const context=await browser.newContext({viewport:{width:390,height:844},colorScheme:'dark',timezoneId:'Pacific/Auckland',...(saved?{storageState:saved}: {})});
// Shift Date only. RNGH tap gestures and RN animation timers retain the browser's
// real performance/timer/event clocks; a frozen Date or Playwright fake timers
// can prevent an actual gesture from completing.
await context.addInitScript(({target})=>{const OriginalDate=globalThis.Date;const offset=OriginalDate.parse(target)-OriginalDate.now();function ShiftedDate(...args){if(!new.target)return new OriginalDate(OriginalDate.now()+offset).toString();return Reflect.construct(OriginalDate,args.length?args:[OriginalDate.now()+offset],new.target);}Object.setPrototypeOf(ShiftedDate,OriginalDate);ShiftedDate.prototype=OriginalDate.prototype;ShiftedDate.now=()=>OriginalDate.now()+offset;globalThis.Date=ShiftedDate;},{target:'2027-05-01T00:00:00Z'});
const page=await context.newPage();page.setDefaultTimeout(40000);
const errors=[],consoleErrors=[],warnings=[],expectedOnboardingDiagnostics=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error'){const entry={message:m.text(),location:m.location()};const path=new URL(entry.location.url||origin).pathname;if((phase==='signup'&&((path==='/api/me'&&entry.message.includes('401'))||(path==='/api/business-profile'&&entry.message.includes('404'))))||(phase==='locks'&&path==='/api/journal-entries'&&entry.message.includes('409')))expectedOnboardingDiagnostics.push(entry);else consoleErrors.push(entry);}if(m.type()==='warning')warnings.push(m.text());});
const fill=(label,value)=>page.getByLabel(label,{exact:true}).last().fill(value);
const click=label=>page.getByRole('button',{name:label,exact:true}).last().click();
const shot=async(name,locator)=>{if(locator)await locator.evaluate(e=>e.scrollIntoView({block:'center'}));await page.screenshot({path:`${out}/${name}.png`,animations:'disabled'});};
async function api(route,method='GET',data,status=200){const r=await context.request.fetch(apiOrigin+route,{method,data,headers:{Origin:origin}});assert.equal(r.status(),status,`${method} ${route}: ${await r.text()}`);return status===204?null:r.json();}
async function more(label){await page.goto(origin,{waitUntil:'networkidle',timeout:180000});await page.getByText('More',{exact:true}).last().click();await page.getByText(label,{exact:true}).last().click();}
async function date(label,value){await click(label);await click('Choose a custom date');await fill('Custom date (YYYY-MM-DD)',value);await click('Confirm selected date');await page.waitForTimeout(400);}
