 async function uiPost(route,action,status=201){const pending=page.waitForResponse(r=>new URL(r.url()).pathname===route&&r.request().method()==='POST');await action();const r=await pending;assert.equal(r.status(),status,await r.text());return r.json();}
 async function invoiceFor(key,suffix,net,issue,due){
  if(!state[key]){await page.goto(origin,{waitUntil:'networkidle'});await page.getByText('New invoice',{exact:true}).first().click();if(await page.getByRole('radio',{name:'Add someone new',exact:true}).count())await page.getByRole('radio',{name:'Add someone new',exact:true}).click();await fill('Customer name',`Harbour Customer ${suffix}`);await fill('Email',`customer-${suffix.toLowerCase()}@example.test`);await click('Continue');await fill('Description',`${suffix} services`);await fill('Amount',net);await click('Continue');state[key]=await uiPost('/api/invoices',()=>click('Create draft'));await persist();}
  const invoice=state[key];if((await api(`/api/invoices/${invoice.id}`)).status==='draft'){await page.goto(`${origin}/invoices/${invoice.id}`,{waitUntil:'networkidle'});await page.getByText('Edit',{exact:true}).last().click();await date('Invoice Date',issue);await date('Due Date',due);await click('Update');await page.goto(`${origin}/invoices/${invoice.id}`,{waitUntil:'networkidle'});await click('Change invoice status');await page.getByRole('button',{name:'Sent. Sent and awaiting payment',exact:true}).click();}state[key]=await api(`/api/invoices/${invoice.id}`);assert.equal(state[key].date,issue);await persist();return state[key];
 }
 async function receiveInvoice(invoice,amount,day,reference){await page.goto(`${origin}/invoices/${invoice.id}`,{waitUntil:'networkidle'});await click('Record payment');if(reference==='NOV-RECEIPT-C'&&!state.overpaymentChecked){const before=await api('/api/payments');await fill('Payment amount','1150.01');await page.getByRole('button',{name:'Record payment',exact:true}).last().click();await page.getByText('Amount cannot exceed the balance due.',{exact:true}).waitFor();assert.deepEqual(await api('/api/payments'),before);await shot('38a-overpayment-prevented',page.getByText('Amount cannot exceed the balance due.',{exact:true}));state.overpaymentChecked={attempt:'1150.01',invoiceBalance:'1150.00',clientBlocked:true,noPaymentsChanged:true};await persist();}await fill('Payment amount',amount);await fill('Payment date',day);await fill('Payment reference',reference);await page.getByRole('button',{name:'Bank Transfer',exact:true}).click();return uiPost('/api/payments',()=>page.getByRole('button',{name:'Record payment',exact:true}).last().click());}
