 function assertReport(r,e,label){if(r.balanceSheet.accumulatedEarnings!==undefined)assert.equal(r.balanceSheet.accumulatedEarnings,e.balanceSheet.accumulatedEarnings,`${label} server earnings bridge`);const numbers={bank:`BANK-${state.bank.id.slice(0,8).toUpperCase()}`,capital:'3000',receivables:'1200',sales:'4000',outputGst:'2200',inputGst:'2150',operatingCosts:'5000',payables:'2100',customerCredit:'2300'};for(const row of e.closingTrialBalance.rows){const actual=r.trialBalance.rows.find(x=>x.accountNumber===numbers[row.accountRole]);assert.ok(actual,`${label} ${row.accountRole}`);assert.equal(actual.closingDebit,row.debit);assert.equal(actual.closingCredit,row.credit);}if(e.openingTrialBalance)for(const row of e.openingTrialBalance.rows){const actual=r.trialBalance.rows.find(x=>x.accountNumber===numbers[row.accountRole]);assert.equal(actual.openingDebit,row.debit,`${label} opening ${row.accountRole} debit`);assert.equal(actual.openingCredit,row.credit,`${label} opening ${row.accountRole} credit`);}for(const key of ['revenue','expenses','netIncome'])assert.equal(r.profitLoss[key],e.profitLoss.accrual[key],`${label} PL ${key}`);for(const key of ['assets','liabilities','equity','balanced'])assert.equal(r.balanceSheet[key],e.balanceSheet[key],`${label} BS ${key}`);for(const name of ['receivablesAging','payablesAging'])for(const key of ['total','current','days1To30','days31To60','days61To90','over90','unallocatedControl'])assert.equal(r[name][key]??'0.00',e[name][key],`${label} ${name}.${key}`);assert.equal(r.trialBalance.closingDebits,e.closingTrialBalance.totalDebits);assert.equal(r.trialBalance.closingCredits,e.closingTrialBalance.totalCredits);if(e.cashFlow)for(const key of ['openingCash','inflows','outflows','closingCash','netCashFlow'])assert.equal(r.cashFlow[key],e.cashFlow[key],`${label} cash ${key}`);if(e.gst)for(const [key,paperKey]of[['outputGst','output'],['inputGst','input'],['netGst','net']])assert.equal(r.taxSummary[key],e.gst.invoice[paperKey],`${label} GST ${key}`);}
